"""Document the completed B.14 investigation without changing numerical outputs."""
from pathlib import Path
import json,math,hashlib
P=Path(__file__).resolve().parent;R=P.parent;W=R.parent
history=json.loads((P/'historical_code_results.json').read_text());fit=json.loads((P/'historical_fit.json').read_text());summary=json.loads((P/'investigation_summary.json').read_text());source=json.loads((P/'source_provenance.json').read_text())
t=json.loads((R/'tables_review/table_data.json').read_text())['TB14'];target={(c['audit_row'],c['audit_column']):c['original']for r in t['rows']for c in r.get('cells',[])if 'audit_column'in c}
p_evidence=[]
for z in history:
 published=target[(z['variable_name'],f"h{z['horizon']} p")];q=z['source_code_test_median_signed']['p_value'];tol=.005+3*math.sqrt(q*(1-q)/10000)
 p_evidence.append(dict(variable=z['variable'],horizon=z['horizon'],published_p=published,exact_source_code_statistic_p=q,rounding_plus_three_mc_standard_errors=tol,compatible=abs(published-q)<=tol+1e-9))
findings=[
 {'id':'F1','finding':'The published caption defines a per-quarter minimum individual absolute error in BOTH surveys. The archived R best-OOS function instead selects one AI name across time and compares it with HUMAN MEDIANS.','evidence':['Simulating_SPF_processing/functions/tab_forecast_accuracy_best_outofsample.R:20-47','Simulating_SPF_processing/functions/tab_forecast_accuracy_best_outofsample.R:62-89','replication_2026-10-31/originals/page_065.txt'],'certainty':'direct source contradiction'},
 {'id':'F2','finding':'The archived function reports MAEs for data_ts2, but computes p-values using data_ts. Its statistic is difference in signed mean errors, not difference in MAEs. Thus the test uses median survey forecasts rather than the selected best forecasts reported in the table.','evidence':['Simulating_SPF_processing/functions/tab_forecast_accuracy_best_outofsample.R:93-126','historical_code_results.json'],'certainty':'direct code evidence'},
 {'id':'F3','finding':'The best-OOS file and ordinary OOS file define the same function name, tab_forecast_accuracy_outofsample. Alphabetical sourcing in the driver loads the ordinary function later, and the driver has no separate best-OOS call. A fresh current driver does not generate the archived B.14 output.','evidence':['Simulating_SPF_processing/tables_figures_all.R:1-4','Simulating_SPF_processing/tables_figures_all.R:104-107','Simulating_SPF_processing/functions/tab_forecast_accuracy_best_outofsample.R:2','Simulating_SPF_processing/functions/tab_forecast_accuracy_outofsample.R:1'],'certainty':'direct code evidence'},
 {'id':'F4','finding':'Current preparation branches on the literal substring outofsample. The old workbook matches it (2024-only sample, horizons 0/1/2); the currently selected _oos.xlsx filename does not (includes 2023 and horizons 0/1/4). The old filename also skips local construction of SPFmicrodata_long even though it is subsequently referenced. These source versions are not a self-contained reproduction of the old table.','evidence':['Simulating_SPF_processing/functions/prepare_data.R:21-26','Simulating_SPF_processing/functions/prepare_data.R:73-76','Simulating_SPF_processing/functions/prepare_data.R:437-499','Simulating_SPF_processing/tables_figures_all.R:34-35'],'certainty':'direct code evidence'},
 {'id':'F5','finding':'The historical AI workbook has 492 raw rows, 260 in 2024 (65 per quarter). The current workbook has 1574 raw rows and 1561 after supplied cleaning, with 798 named rows in 2024 (199,199,199,201). Neither raw workbook has duplicate Name-quarter rows. The final calculation uses the current driver-selected workbook and reconstructs its GDP-price scale and named-row rules.','evidence':['raw_validation.json'],'certainty':'raw-file verified'},
 {'id':'F6','finding':'Archived h2 plot paths independently stop at origin 2024Q1 (target 2024Q3) for CPI, Core CPI, PCE and Core PCE. Other variables stop at origin 2024Q2 (target 2024Q4). This supports an older variable-specific availability cutoff; it was not chosen by minimizing table discrepancies.','evidence':['archived_figure_cutoff_evidence.json'],'certainty':'direct vector-path evidence, historical sample inference'},
 {'id':'F7','finding':'Using the old AI workbook, one best name across time, and the archived-figure-supported cutoff recovers 63/66 published AI MAEs within half a displayed unit. The three remaining AI discrepancies are all AAA bond yield. Raw human medians recover 62/66 human MAEs. Applying current median clipping also recovers 62/66 but changes which four miss, so the current clipping code cannot explain all historical human entries consistently.','evidence':['historical_fit.json','historical_code_results.json'],'certainty':'computed provenance evidence; complete original pipeline unresolved'},
 {'id':'F8','finding':'A selected name may have missing forecasts. For example, NGDP h1 selects Sacha Gelfer, whose mean uses two forecasts, while the source path keeps three human-median quarters. This explains published AI MAEs below the per-quarter-minimum average over all eligible quarters; it is an unequal-sample, across-time selection effect.','evidence':['historical_quarter_results.json','historical_code_results.json'],'certainty':'raw-source and code verified'},
 {'id':'F9','finding':'The historical median signed-error test is compatible with 64/66 published p-values after allowing two-decimal display rounding and three standard errors of a 10000-draw Monte Carlo estimator. Remaining failures are Housing h1 and AAA bond h2. This supports the wrong-test-input provenance but does not prove an exact historical seed or data snapshot.','evidence':['historical_p_provenance.json'],'certainty':'statistical diagnostic, not exact reproduction'},
 {'id':'F10','finding':'The verified table implements the caption on current supplied data: forecast origins 2024Q1-Q4; horizons 0,1,2; target date origin+h; minimum individual absolute error per survey and quarter; matched quarterly samples; exact two-sided sign-flip test on MAE differences. Future target quarters in 2025 are used when supplied actuals exist. Only CPROF has missing 2025Q1/Q2 actuals, giving one N=3 and one N=2 test; the other 64 tests have N=4.','evidence':['verified_table.json','verified_results.json','verified_quarter_results.json','raw_validation.json'],'certainty':'independently raw-validated recalculation; explicit forecast-origin sample interpretation'},
 {'id':'F11','finding':'Exact tests enumerate all 2^N assignments, eliminating Monte Carlo noise. With at most four paired quarters, the minimum two-sided exact p-value here is 0.125; none meets the paper significance-star thresholds. This is a method-faithful exact version of a paired randomization test of MAE differences, not recovery of the paper seed.','evidence':['verified_results.json'],'certainty':'exact finite enumeration'},
 {'id':'F12','finding':'Final display uses decimal arithmetic on source forecast and actual values for minima and means, then ROUND_HALF_EVEN at two decimals. Float estimates are retained separately. UNEMP h0 AI is exactly 0.075 and displays 0.08; p=0.125 displays 0.12. Differences from a published Monte Carlo p-value of 0.13 are not merely formatting differences.','evidence':['rounding_boundaries.json','verified_results.json'],'certainty':'deterministic arithmetic and display policy'},
]
(P/'historical_p_provenance.json').write_text(json.dumps(p_evidence,indent=2))
evidence={'status':'Defensible caption-accurate current-data results verified; original published pipeline only partly recovered','primary_output':'verified_table.json','summary':summary,'findings':findings,'historical_residual_point_cells':[x for x in fit if not x['within_half_display_unit']],'source_files_unchanged':source['all_source_files_unchanged'],'two_archived_table_files_identical':source['sha256']['Simulating_SPF_processing/tables/forecast_accuracy_best_forecasters_oos.txt']==source['sha256']['latest draft/tables/forecast_accuracy_best_forecasters_oos.txt']}
(P/'evidence.json').write_text(json.dumps(evidence,indent=2))
text='TABLE B.14 INVESTIGATION\n\n'+evidence['status']+'\n\n'
text+='Final PDF-ready table: verified_table.json\nNumerical results: verified_results.json / .csv\nQuarter-level winners, source forecasts, actuals and errors: verified_quarter_results.json / .csv\nRaw reconciliation: raw_validation.json\nHistorical reconstruction: historical_code_results.json, historical_quarter_results.json, historical_fit.json\nSource hashes: source_provenance.json\nRebuild: python3 replication_2026-10-31/tableB14_investigation/investigate_table_b14.py\nDocument evidence: python3 replication_2026-10-31/tableB14_investigation/write_evidence.py\n\n'
for f in findings:text+=f["id"]+'. '+f['finding']+'\nEvidence: '+', '.join(f['evidence'])+'\nStatus: '+f['certainty']+'\n\n'
text+='The verified table is a new, coherent calculation of the stated statistic using the current source inputs. It must not be described as a full numerical recovery of the published historical run. The supplied actuals are used as supplied; this local investigation does not replace them with newly downloaded vintages. No original research file or PDF builder was modified.\n'
(P/'README.txt').write_text(text)
print(json.dumps({'findings':len(findings),'historical_p_compatible':sum(x['compatible']for x in p_evidence),'evidence':str(P/'evidence.json'),'canonical_sha256':hashlib.sha256((P/'verified_table.json').read_bytes()).hexdigest()},indent=2))
